WITH exploded AS (SELECT id, plan, effective_from, currency, EXPLODE(tier_limits) AS tier_value FROM price_tiers), enriched AS (SELECT id, plan, effective_from, currency, DENSE_RANK() OVER (ORDER BY tier_value) tier_value_dense_rank, STDDEV_SAMP(tier_value) OVER (PARTITION BY currency) currency_stddev_samp_tier_value, MIN(tier_value) OVER (PARTITION BY plan) plan_min_tier_value, SUM(tier_value) OVER (PARTITION BY currency, plan) currency_sum_tier_value FROM exploded), scored AS (SELECT *, COUNT(currency_sum_tier_value) OVER (PARTITION BY plan) plan_count_currency_sum_tier_value, STDDEV_SAMP(currency_stddev_samp_tier_value) OVER (PARTITION BY plan) plan_stddev_samp_currency_stddev_samp_tier_value, PERCENT_RANK() OVER (ORDER BY tier_value_dense_rank DESC NULLS LAST) tier_value_dense_rank_percent_rank FROM enriched), valid AS (SELECT id, plan, effective_from, currency, tier_value_dense_rank, currency_sum_tier_value, plan_count_currency_sum_tier_value, plan_stddev_samp_currency_stddev_samp_tier_value, COALESCE(plan_min_tier_value, 0) plan_min_tier_value_filled, currency_sum_tier_value + plan_min_tier_value currency_sum_tier_value_plus_plan_min_tier_value FROM scored WHERE currency_sum_tier_value IS NOT NULL), filtered AS (SELECT *, currency_sum_tier_value_plus_plan_min_tier_value + plan_min_tier_value_filled currency_sum_tier_value_plus_plan_min_tier_value_plus_plan_min_tier_value_filled, plan_count_currency_sum_tier_value * currency_sum_tier_value plan_count_currency_sum_tier_value_times_currency_sum_tier_value FROM valid WHERE effective_from > DATE '2024-04-10' AND plan = 'enterprise'), enriched_price_tiers AS (SELECT id, plan_count_currency_sum_tier_value, plan_stddev_samp_currency_stddev_samp_tier_value, plan_min_tier_value_filled, currency_sum_tier_value_plus_plan_min_tier_value, plan_count_currency_sum_tier_value_times_currency_sum_tier_value, STDDEV_SAMP(plan_count_currency_sum_tier_value) OVER (PARTITION BY plan) plan_stddev_samp_plan_count_currency_sum_tier_value, STDDEV_SAMP(currency_sum_tier_value) OVER (PARTITION BY currency, plan) currency_stddev_samp_currency_sum_tier_value FROM filtered), with_windows AS (SELECT id, plan_count_currency_sum_tier_value, plan_count_currency_sum_tier_value_times_currency_sum_tier_value, plan_stddev_samp_plan_count_currency_sum_tier_value, currency_stddev_samp_currency_sum_tier_value, PERCENT_RANK() OVER (ORDER BY currency_sum_tier_value_plus_plan_min_tier_value DESC NULLS LAST) currency_sum_tier_value_plus_plan_min_tier_value_percent_rank, CUME_DIST() OVER (ORDER BY plan_stddev_samp_plan_count_currency_sum_tier_value DESC NULLS LAST) plan_stddev_samp_plan_count_currency_sum_tier_value_cume_dist, DENSE_RANK() OVER (ORDER BY plan_stddev_samp_plan_count_currency_sum_tier_value NULLS LAST) plan_stddev_samp_plan_count_currency_sum_tier_value_dense_rank, DENSE_RANK() OVER (ORDER BY plan_count_currency_sum_tier_value_times_currency_sum_tier_value DESC) plan_count_currency_sum_tier_value_times_currency_sum_tier_value_dense_rank FROM enriched_price_tiers) SELECT *, CUME_DIST() OVER w_recent plan_stddev_samp_plan_count_currency_sum_tier_value_dense_rank_cume_dist, DENSE_RANK() OVER w_running plan_stddev_samp_plan_count_currency_sum_tier_value_cume_dist_dense_rank, DENSE_RANK() OVER w_recent plan_stddev_samp_plan_count_currency_sum_tier_value_dense_rank_dense_rank FROM with_windows WHERE currency_sum_tier_value_plus_plan_min_tier_value_percent_rank BETWEEN 0.35 AND 0.73 WINDOW w_recent AS (ORDER BY plan_stddev_samp_plan_count_currency_sum_tier_value_dense_rank DESC NULLS FIRST), w_running AS (ORDER BY plan_stddev_samp_plan_count_currency_sum_tier_value_cume_dist DESC);
